//Class Helper Properties & Methods
public static function initLogger(): void
{
    static $loggerSet = false;

    if ($loggerSet)
    {
        return;
    }

    // Fixed: Using fully qualified namespace string to bypass compilation alias limits
    \Joomla\CMS\Log\Log::addLogger(
        [
            'text_file' => 'waca.php',
            'text_entry_format' => '{DATETIME} {PRIORITY} {CATEGORY} {MESSAGE}'
        ],
        \Joomla\CMS\Log\Log::ALL
    );

    $loggerSet = true;
}


/**
 * Example wrapper for error logging.
 */
public static function logError(string $message, array $context = []): void
{
    self::initLogger();

    $fullMessage = $message;

    if (!empty($context))
    {
        $fullMessage .= ' | Context: ' . json_encode(
            $context,
            JSON_UNESCAPED_SLASHES
            | JSON_UNESCAPED_UNICODE
            | JSON_PARTIAL_OUTPUT_ON_ERROR
        );
    }
    \Joomla\CMS\Log\Log::add($fullMessage, \Joomla\CMS\Log\Log::ERROR, 'com_waca');
}

public static function logTrace(string $message, array $context = []): void
{
    static $traceEnabled = null;

       if ($traceEnabled === null)
    {
      //  $params = \Joomla\CMS\Helper\ModuleHelper::getModule('mod_waca')->params ?? null;
      //  $traceEnabled = $params ? (bool) $params->get('enable_trace', 0) : false;
      $traceEnabled = (bool) ComponentHelper::getParams('com_waca')->get('enable_trace', 0);
    }

    if (!$traceEnabled)
    {
        return;
    }

    self::initLogger();

    $fullMessage = $message;

    if (!empty($context))
    {
        $fullMessage .= ' | Context: ' . json_encode(
            $context,
            JSON_UNESCAPED_SLASHES
            | JSON_UNESCAPED_UNICODE
            | JSON_PARTIAL_OUTPUT_ON_ERROR
        );
    }

    \Joomla\CMS\Log\Log::add(
        $fullMessage,
        \Joomla\CMS\Log\Log::NOTICE,
        'com_waca'
    );
}  


public static function getUniversities(string $country): array
{
    try
    {
        $db = Factory::getContainer()->get('db');

        $query = $db->getQuery(true)
            ->select('a.*')
            ->from($db->quoteName('#__waca_university', 'a'))
            ->where('a.published = 1')
            ->where('a.country = ' . $db->quote($country));

        self::logTrace('SQL', ['sql' => (string) $query]);

        $results = $db
            ->setQuery($query)
            ->loadObjectList();

        self::logTrace('SQL', ['results' => $results]);

        return $results;
    }
    catch (\Throwable $e)
    {
        self::logError(
            $e->getMessage(),

      [
            'country'  => $country,
           'exception'=> $e::class,
           'file'     => $e->getFile(),
          'line'     => $e->getLine(),

            ]
        );

        Factory::getApplication()->enqueueMessage(
            Text::_('MOD_WACA_ERROR_LOADING_UNIVERSITIES'),
            'error'
        );

        return [];
    }
}
